// ---- src/lib/reminders.ts ----
// Reminder rules. Pure: given the config and what has been logged, which reminders are due now.
// No imports on purpose: this exact file is also bundled into the Supabase push function
// (supabase/functions/send-reminders), so the app and the server agree on what is due.

type DateKey = string; // YYYY-MM-DD

const diffDays = (a: DateKey, b: DateKey) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);

export interface ReminderConfig {
  enabled: boolean;
  weighIn: { on: boolean; time: string };
  workout: { on: boolean; time: string };
  checkIn: { on: boolean; time: string };
  food: { on: boolean; time: string };
  water: { on: boolean; everyHours: number };
  measurements: { on: boolean; everyDays: number };
  photos: { on: boolean; everyDays: number };
  video: { on: boolean; everyDays: number };
}

export const DEFAULT_REMINDERS: ReminderConfig = {
  enabled: true,
  weighIn: { on: true, time: '07:30' },
  workout: { on: true, time: '18:00' },
  checkIn: { on: true, time: '09:00' },
  food: { on: true, time: '21:00' },
  water: { on: false, everyHours: 3 },
  measurements: { on: true, everyDays: 14 },
  photos: { on: true, everyDays: 14 },
  video: { on: true, everyDays: 28 },
};

export interface ReminderState {
  today: DateKey;
  /** Minutes since local midnight. */
  minutes: number;
  isTrainingDay: boolean;
  weighedIn: boolean;
  trainedOrSkipped: boolean;
  checkedIn: boolean;
  foodLogged: boolean;
  waterMl: number;
  waterTargetMl: number;
  lastMeasurement?: DateKey;
  lastPhoto?: DateKey;
  lastVideo?: DateKey;
}

export interface Due {
  id: string;
  title: string;
  body: string;
  route: string;
}

const toMin = (t: string) => {
  const [h, m] = t.split(':').map(Number);
  return h * 60 + (m || 0);
};

const overdue = (last: DateKey | undefined, today: DateKey, every: number) => !last || diffDays(last, today) >= every;

export function dueReminders(c: ReminderConfig, s: ReminderState): Due[] {
  if (!c.enabled) return [];
  const out: Due[] = [];
  const after = (t: string) => s.minutes >= toMin(t);
  if (c.weighIn.on && after(c.weighIn.time) && !s.weighedIn)
    out.push({ id: 'weigh-in', title: 'Morning weigh-in', body: 'Fasted, after the toilet, before food or water.', route: 'today' });
  if (c.checkIn.on && after(c.checkIn.time) && !s.checkedIn)
    out.push({ id: 'check-in', title: '20-second check-in', body: 'Sleep, energy, soreness, mood, hunger.', route: 'today' });
  if (c.workout.on && s.isTrainingDay && after(c.workout.time) && !s.trainedOrSkipped)
    out.push({ id: 'workout', title: 'Workout today', body: "Today's session is not logged yet.", route: 'today' });
  if (c.food.on && after(c.food.time) && !s.foodLogged)
    out.push({ id: 'food', title: 'Log your food', body: 'Nothing logged today yet.', route: 'food' });
  if (c.water.on && s.minutes >= 9 * 60 && s.minutes <= 21 * 60) {
    // Expected intake rises linearly from 09:00 to 21:00.
    const expected = (s.waterTargetMl * (s.minutes - 9 * 60)) / (12 * 60);
    if (s.waterMl < expected - 500) out.push({ id: `water-${Math.floor(s.minutes / (c.water.everyHours * 60))}`, title: 'Water', body: `${(s.waterMl / 1000).toFixed(1)} L so far today.`, route: 'food' });
  }
  if (c.measurements.on && after('08:00') && overdue(s.lastMeasurement, s.today, c.measurements.everyDays))
    out.push({ id: 'measurements', title: 'Measurement day', body: 'Neck and waist at the navel, fasted.', route: 'body/measure' });
  if (c.photos.on && after('08:00') && overdue(s.lastPhoto, s.today, c.photos.everyDays))
    out.push({ id: 'photos', title: 'Photo day', body: 'Front, side and back with the ghost camera.', route: 'media' });
  if (c.video.on && after('08:00') && overdue(s.lastVideo, s.today, c.video.everyDays))
    out.push({ id: 'video', title: 'Pose video', body: 'Monthly pose video.', route: 'media' });
  return out;
}

/** Notification bookkeeping: each reminder id fires at most once per day. */
export function notYetNotified(due: Due[], sent: Record<string, DateKey>, today: DateKey): Due[] {
  return due.filter((d) => sent[d.id] !== today);
}

// ---- scripts/push-handler.ts ----
// Supabase Edge Function body (Deno). Combined with src/lib/reminders.ts by
// scripts/build-push-function.mjs into supabase/functions/send-reminders/index.ts.
// Runs every 15 minutes (pg_cron): for each user with a push subscription, works out which
// reminders are due in their time zone and sends each one at most once a day.

const SUBJECT = 'https://pradheshkumar.github.io/gym-tracker/';

const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
  auth: { persistSession: false },
});
const VAPID_PRIVATE_KEY = Deno.env.get('VAPID_PRIVATE_KEY');
if (VAPID_PRIVATE_KEY) webpush.setVapidDetails(SUBJECT, VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY);

interface Sub {
  endpoint: string;
  user_id: string;
  p256dh: string;
  auth: string;
  tz: string;
}

function localNow(tz: string) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date());
  const g = (t: string) => parts.find((p) => p.type === t)!.value;
  const today = `${g('year')}-${g('month')}-${g('day')}`;
  const wd = new Date(today + 'T00:00:00Z').getUTCDay();
  return { today, minutes: Number(g('hour')) * 60 + Number(g('minute')), weekday: wd === 0 ? 7 : wd };
}

async function userState(uid: string, tz: string) {
  const { today, minutes, weekday } = localNow(tz);
  const base = () => db.from('records').select('id, data').eq('user_id', uid).eq('deleted', false);
  const one = async (tbl: string, id: string) => (await base().eq('tbl', tbl).eq('id', id).maybeSingle()).data?.data as any;
  const any = async (q: any) => ((await q.limit(1)).data ?? []).length > 0;

  const [configRow, media, weigh, check, water, plan, phases, sets, daySkips, food, waist] = await Promise.all([
    one('kv', 'reminders'),
    one('kv', 'mediaSummary'),
    one('weighins', today),
    one('checkins', today),
    one('hydration', today),
    one('plan', String(weekday)),
    base().eq('tbl', 'phases'),
    any(base().eq('tbl', 'sets').eq('data->>date', today)),
    any(base().eq('tbl', 'skips').eq('data->>date', today).is('data->>exerciseId', null)),
    any(base().eq('tbl', 'foodlog').eq('data->>date', today)),
    base().eq('tbl', 'measurements').eq('data->>site', 'waist (navel)').order('data->>date', { ascending: false }).limit(1),
  ]);

  const allPhases = ((phases.data ?? []) as { data: any }[]).map((r) => r.data).sort((a, b) => a.order - b.order);
  const phase = allPhases.find((p) => p.start <= today && today <= p.end) ?? allPhases.find((p) => p.start > today);
  const config: ReminderConfig = { ...DEFAULT_REMINDERS, ...(configRow?.value ?? {}) };
  const state: ReminderState = {
    today,
    minutes,
    isTrainingDay: !!plan && !plan.rest,
    weighedIn: !!weigh,
    trainedOrSkipped: sets || daySkips,
    checkedIn: !!check,
    foodLogged: food,
    waterMl: water?.ml ?? 0,
    waterTargetMl: (phase?.waterL ?? 3) * 1000,
    lastMeasurement: (waist.data?.[0] as any)?.data?.date,
    lastPhoto: media?.value?.lastPhoto,
    lastVideo: media?.value?.lastVideo,
  };
  return { today, due: dueReminders(config, state) };
}

Deno.serve(async () => {
  if (!VAPID_PRIVATE_KEY) return new Response(JSON.stringify({ error: 'Secret VAPID_PRIVATE_KEY is not set' }), { status: 500 });
  const { data, error } = await db.from('push_subscriptions').select('*');
  if (error) return new Response(JSON.stringify({ error: error.message }), { status: 500 });
  const byUser = new Map<string, Sub[]>();
  for (const s of (data ?? []) as Sub[]) byUser.set(s.user_id, [...(byUser.get(s.user_id) ?? []), s]);

  let sent = 0;
  for (const [uid, subs] of byUser) {
    const { today, due } = await userState(uid, subs[0].tz || 'Asia/Kolkata');
    if (!due.length) continue;
    const { data: log } = await db.from('push_log').select('reminder').eq('user_id', uid).eq('day', today);
    const done = new Set((log ?? []).map((r: { reminder: string }) => r.reminder));
    for (const d of due.filter((x) => !done.has(x.id))) {
      const payload = JSON.stringify({ title: d.title, body: d.body, tag: d.id, route: d.route });
      for (const s of subs) {
        try {
          await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, payload, { TTL: 3600 });
          sent++;
        } catch (e) {
          const code = (e as { statusCode?: number }).statusCode;
          // The browser dropped this subscription: forget it.
          if (code === 404 || code === 410) await db.from('push_subscriptions').delete().eq('endpoint', s.endpoint);
        }
      }
      await db.from('push_log').upsert({ user_id: uid, day: today, reminder: d.id }, { ignoreDuplicates: true });
    }
  }
  return new Response(JSON.stringify({ users: byUser.size, sent }), { headers: { 'Content-Type': 'application/json' } });
});
